#
# src/sysdep/sdlgpu/shaders/build-shaders.sh: Compile the default shaders
# to SPIR-V and write them as C arrays to ../shaders-spirv.i, which is
# included by shader.c.  The generated file is checked in, so this only
# needs to be run after changing the shader sources.
#
# Requires glslc (Vulkan SDK or shaderc).  Usage:
#     ./build-shaders.sh [path/to/glslc]

set -e
cd "$(dirname "$0")"
GLSLC="${1:-$(command -v glslc || echo "$HOME/VulkanSDK/1.4.363.1/macOS/bin/glslc")}"
OUT=../shaders-spirv.i
TMP=$(mktemp -d)
trap 'rm -rf "$TMP"' EXIT

compile() {  # compile <stage> <source> <name> [defines...]
    stage=$1; src=$2; name=$3; shift 3
    "$GLSLC" -fshader-stage="$stage" --target-env=vulkan1.0 -O "$@" \
        -o "$TMP/$name.spv" "$src"
    printf 'static const uint8_t %s[] = {' "$name"
    od -An -v -tu1 "$TMP/$name.spv" | tr -s ' \n' ',' | sed 's/^,//; s/,$//'
    printf '};\n'
}

{
    echo '/* Generated by build-shaders.sh from default.vert / default.frag.'
    echo ' * Do not edit by hand. */'
    for tex in 0 1; do
        for color in 0 1; do
            compile vert default.vert "spirv_vertex_t${tex}_c${color}" \
                -DHAS_TEX=$tex -DHAS_COLOR=$color
        done
    done
    compile frag default.frag spirv_fragment
} > "$OUT"
echo "Wrote $OUT"
